    class Bindings
    {
        uintptr_t module{};
    public:
        Calls calls;
        ControlCalls controls;
        bool Bind(HMODULE image)
        {
            module = 0;
            if (!calls.Bind(image)) return false;
            const auto base = reinterpret_cast<uintptr_t>(image);
            for (const auto& guard : hostPrefixes)
            {
                const auto at = reinterpret_cast<const uint8_t*>(base + guard.rva);
                if (!Readable(at, guard.bytes.size())) return false;
                for (size_t i = 0; i < guard.bytes.size(); ++i)
                    if ((at[i] & guard.mask[i]) != (guard.bytes[i] & guard.mask[i])) return false;
            }
            for (const auto& table : hostTables)
                for (size_t i = 0; i < table.targets.size(); ++i)
                    if (Read<uintptr_t>(reinterpret_cast<void*>(base + table.rva), i * 4) != base + table.targets[i]) return false;
            module = base;
            return true;
        }
        uintptr_t Base() const { return module; }
        template<class Function> Function At(uint32_t rva) const { return reinterpret_cast<Function>(module + rva); }
        void* Allocate(size_t bytes) const
        {
            return module && bytes && bytes <= 4096 ? At<void* (__cdecl*)(size_t)>(0x100FB0)(bytes) : nullptr;
        }
        void Free(void* memory) const { if (module && memory) At<void (__cdecl*)(void*)>(0x100FD0)(memory); }
        void Select(void* row, bool selected) const
        {
            const auto table = Read<uintptr_t>(row, 0).value_or(0);
            const auto changed = Read<uintptr_t>(reinterpret_cast<void*>(table), 200).value_or(0);
            // Native09410 invokes this common BaseControl selector for every
            // original subclass too; it is not restricted to the TextCtrl type.
            if (module && Readable(row, 84) && table >= module && table < module + 0x194000 &&
                changed >= module && changed < module + 0x194000 && Ready::Executable(changed))
                At<char (__thiscall*)(void*, char)>(0x133170)(row, selected ? 1 : 0);
        }
        void StringText(void* string, const wchar_t* text) const
        {
            if (module && Readable(string, 124) && text) At<void (__thiscall*)(void*, const wchar_t*)>(0x1330A0)(string, text);
        }
        std::optional<std::wstring> StringText(void* string) const
        {
            const auto length = Read<uint32_t>(string, 68).value_or(UINT32_MAX);
            const auto capacity = Read<uint32_t>(string, 72).value_or(0);
            if (length > 4096 || capacity < length) return {};
            const auto data = capacity < 8 ? reinterpret_cast<const wchar_t*>(reinterpret_cast<uint8_t*>(string) + 52) :
                Read<const wchar_t*>(string, 52).value_or(nullptr);
            if (!Readable(data, (static_cast<size_t>(length) + 1) * sizeof(wchar_t)) || data[length]) return {};
            return std::wstring(data, length);
        }
    };
